import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { adminApi } from '../api/admin';
import { useAuth } from '../context/AuthContext';
import { useShop } from '../context/ShopContext';
import {
  ArrowLeft,
  ShoppingBag,
  Truck,
  RotateCcw,
  AlertTriangle,
  CheckCircle2,
  Clock,
  Send,
  Loader2,
  FileText,
  EyeOff,
  RefreshCw,
  Ban,
  ShieldAlert,
} from 'lucide-react';
import ConfirmModal from '../components/ConfirmModal';

export const AdminOrderDetail: React.FC = () => {
  const { orderId } = useParams<{ orderId: string }>();
  const { user, hasRole } = useAuth();
  const { formatPrice } = useShop();

  const isFinance = hasRole(['admin', 'super_admin', 'finance']);
  const canCancel = hasRole(['admin', 'super_admin', 'manager', 'support']);
  const canRetry = hasRole(['admin', 'super_admin']);
  const canShip = hasRole(['admin', 'super_admin', 'manager']);

  const [orderDetail, setOrderDetail] = useState<any | null>(null);
  const [timeline, setTimeline] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);

  // Form states
  const [noteInput, setNoteInput] = useState('');
  const [submittingNote, setSubmittingNote] = useState(false);

  const [cancelReason, setCancelReason] = useState('');
  const [submittingCancel, setSubmittingCancel] = useState(false);

  const [carrierInput, setCarrierInput] = useState('National Post');
  const [trackingInput, setTrackingInput] = useState('');
  const [shippingStatus, setShippingStatus] = useState<'SHIPPED' | 'DELIVERED'>('SHIPPED');
  const [submittingShipping, setSubmittingShipping] = useState(false);

  const [retryingFulfillment, setRetryingFulfillment] = useState(false);

  const fetchOrderData = async () => {
    if (!orderId) return;
    setLoading(true);
    setError(null);
    try {
      const [detailRes, timelineRes] = await Promise.all([
        adminApi.getOrderDetail(orderId),
        adminApi.getOrderTimeline(orderId).catch(() => ({ events: [] })),
      ]);
      setOrderDetail(detailRes);
      setTimeline(timelineRes.events || []);
    } catch (err: any) {
      setError(err?.error || err?.message || 'Could not load order record.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrderData();
  }, [orderId]);

  const handleAddNote = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!orderId || !noteInput.trim()) return;

    setSubmittingNote(true);
    setActionSuccess(null);
    try {
      await adminApi.addOrderNote(orderId, noteInput.trim());
      setNoteInput('');
      setActionSuccess('Internal staff note added successfully.');
      await fetchOrderData();
    } catch (err: any) {
      alert(err?.error || err?.message || 'Failed to add note.');
    } finally {
      setSubmittingNote(false);
    }
  };

  const [actionError, setActionError] = useState<string | null>(null);
  const [confirmCancelOpen, setConfirmCancelOpen] = useState(false);

  const handleCancelOrder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!orderId || !cancelReason.trim()) return;
    setConfirmCancelOpen(true);
  };

  const executeCancelOrder = async () => {
    if (!orderId || !cancelReason.trim()) return;
    setConfirmCancelOpen(false);
    setSubmittingCancel(true);
    setActionSuccess(null);
    setActionError(null);
    try {
      await adminApi.cancelOrder(orderId, cancelReason.trim());
      setCancelReason('');
      setActionSuccess('Order cancelled successfully.');
      await fetchOrderData();
    } catch (err: any) {
      setActionError(err?.error || err?.message || 'Failed to cancel order.');
    } finally {
      setSubmittingCancel(false);
    }
  };

  const handleRetryFulfillment = async () => {
    if (!orderId) return;
    setRetryingFulfillment(true);
    setActionSuccess(null);
    setActionError(null);
    try {
      await adminApi.retryOrderFulfillment(orderId);
      setActionSuccess('Fulfillment worker retried successfully.');
      await fetchOrderData();
    } catch (err: any) {
      setActionError(err?.error || err?.message || 'Order is not eligible for fulfillment retry.');
    } finally {
      setRetryingFulfillment(false);
    }
  };

  const handleUpdateShipping = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!orderId) return;

    if (shippingStatus === 'SHIPPED' && (!carrierInput.trim() || !trackingInput.trim())) {
      setActionError('Carrier name and tracking number are required when setting status to SHIPPED.');
      return;
    }

    setSubmittingShipping(true);
    setActionSuccess(null);
    try {
      await adminApi.updateOrderShipping(orderId, {
        status: shippingStatus,
        carrier: carrierInput.trim() || undefined,
        trackingNumber: trackingInput.trim() || undefined,
      });
      setActionSuccess('Shipping milestone updated and logged to audit ledger.');
      await fetchOrderData();
    } catch (err: any) {
      alert(err?.error || err?.message || 'Failed to update shipment status.');
    } finally {
      setSubmittingShipping(false);
    }
  };

  if (loading) {
    return (
      <div className="max-w-4xl mx-auto px-4 py-24 text-center">
        <Loader2 size={32} className="animate-spin text-emerald-500 mx-auto mb-3" />
        <p className="text-xs font-mono text-slate-500">Loading order #{orderId}...</p>
      </div>
    );
  }

  if (error || !orderDetail) {
    return (
      <div className="max-w-md mx-auto px-4 py-24 text-center">
        <AlertTriangle size={32} className="text-rose-500 mx-auto mb-3" />
        <h1 className="font-display text-lg font-bold text-slate-900 dark:text-white mb-2">
          Order Record Unavailable
        </h1>
        <p className="text-xs text-slate-500 dark:text-slate-400 mb-6">{error || 'Order record could not be loaded.'}</p>
        <Link
          to="/admin/orders"
          className="inline-flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-xs font-semibold"
        >
          <ArrowLeft size={13} />
          <span>Back to Orders Queue</span>
        </Link>
      </div>
    );
  }

  const order = orderDetail.order || orderDetail;
  const isEligibleRetry = order.status === 'PAID' && (order.fulfillmentStatus === 'FAILED' || order.fulfillmentStatus === 'PENDING');

  return (
    <div className="max-w-5xl mx-auto px-4 py-12">
      <Link
        to="/admin/orders"
        className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-slate-900 dark:hover:text-white transition-colors mb-6"
      >
        <ArrowLeft size={13} />
        <span>Back to Orders Queue</span>
      </Link>

      {actionSuccess && (
        <div className="p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-600 dark:text-emerald-400 text-xs mb-6 flex items-start gap-2.5">
          <CheckCircle2 size={16} className="shrink-0 mt-0.5" />
          <span>{actionSuccess}</span>
        </div>
      )}

      {actionError && (
        <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-600 dark:text-rose-400 text-xs mb-6 flex items-start gap-2.5">
          <AlertTriangle size={16} className="shrink-0 mt-0.5" />
          <span>{actionError}</span>
        </div>
      )}

      <div className="p-8 rounded-3xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm space-y-8">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-6 border-b border-slate-100 dark:border-slate-800">
          <div>
            <div className="flex items-center gap-2.5">
              <span className="font-mono text-base font-bold text-slate-900 dark:text-white">
                Order #{order.orderId}
              </span>
              <span className="px-2.5 py-0.5 rounded text-[10px] font-mono font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300">
                {order.status}
              </span>
              <span className="text-[10px] font-mono text-slate-400">
                Fulfillment: {order.fulfillmentStatus || 'NOT_READY'}
              </span>
            </div>
            <p className="text-xs text-slate-400 font-mono mt-1">
              Customer ID: {order.userId} • Created {new Date(order.createdAt).toLocaleString()}
            </p>
          </div>

          <div className="text-left sm:text-right">
            <div className="text-[10px] uppercase font-mono tracking-wider text-slate-400">
              Total Settled
            </div>
            {order.totalAmount !== undefined ? (
              <div className="font-mono text-xl font-bold text-emerald-600 dark:text-emerald-400">
                {formatPrice(order.totalAmount, order.currency)}
              </div>
            ) : (
              <div className="flex items-center gap-1 text-slate-400 text-xs font-mono" title="Redacted for non-finance roles">
                <EyeOff size={12} />
                <span>[Redacted for non-finance role]</span>
              </div>
            )}
          </div>
        </div>

        {/* Action Controls Toolbar */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Fulfillment Retry */}
          {canRetry && (
            <div className="p-5 rounded-2xl bg-slate-50 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 space-y-3">
              <span className="text-xs font-bold text-slate-900 dark:text-white block">
                Fulfillment Retry
              </span>
              <p className="text-[11px] text-slate-500 leading-relaxed">
                Eligible only when status is PAID and fulfillment is FAILED or PENDING.
              </p>
              <button
                type="button"
                disabled={!isEligibleRetry || retryingFulfillment}
                onClick={handleRetryFulfillment}
                className="w-full py-2 px-3 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold disabled:opacity-40 transition-colors"
              >
                {retryingFulfillment ? 'Retrying...' : 'Retry Fulfillment Worker'}
              </button>
            </div>
          )}

          {/* Cancellation */}
          {canCancel && order.status !== 'CANCELLED' && (
            <div className="p-5 rounded-2xl bg-slate-50 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 space-y-3">
              <span className="text-xs font-bold text-rose-600 dark:text-rose-400 block">
                Cancel Order
              </span>
              <p className="text-[11px] text-slate-500 leading-relaxed">
                Requires mandatory reason (1-500 chars). Live payments must be reconciled first.
              </p>
              <form onSubmit={handleCancelOrder} className="space-y-2">
                <input
                  type="text"
                  required
                  maxLength={500}
                  value={cancelReason}
                  onChange={e => setCancelReason(e.target.value)}
                  placeholder="Reason for cancellation..."
                  className="w-full px-3 py-1.5 rounded-lg bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white focus:outline-none"
                />
                <button
                  type="submit"
                  disabled={submittingCancel || !cancelReason.trim()}
                  className="w-full py-2 px-3 rounded-lg bg-rose-600 hover:bg-rose-500 text-white text-xs font-semibold disabled:opacity-40 transition-colors"
                >
                  {submittingCancel ? 'Cancelling...' : 'Confirm Cancellation'}
                </button>
              </form>
            </div>
          )}

          {/* Shipping Update */}
          {canShip && (
            <div className="p-5 rounded-2xl bg-slate-50 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 space-y-3">
              <span className="text-xs font-bold text-slate-900 dark:text-white block">
                Shipping Milestones
              </span>
              <form onSubmit={handleUpdateShipping} className="space-y-2 text-xs">
                <div className="flex gap-2">
                  <select
                    value={shippingStatus}
                    onChange={e => setShippingStatus(e.target.value as any)}
                    className="flex-1 px-2.5 py-1.5 rounded-lg bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 font-mono text-[11px]"
                  >
                    <option value="SHIPPED">SHIPPED</option>
                    <option value="DELIVERED">DELIVERED</option>
                  </select>
                </div>
                {shippingStatus === 'SHIPPED' && (
                  <>
                    <input
                      type="text"
                      value={carrierInput}
                      onChange={e => setCarrierInput(e.target.value)}
                      placeholder="Carrier (e.g., Post, DHL)"
                      className="w-full px-2.5 py-1.5 rounded-lg bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-[11px]"
                    />
                    <input
                      type="text"
                      value={trackingInput}
                      onChange={e => setTrackingInput(e.target.value)}
                      placeholder="Tracking number..."
                      className="w-full px-2.5 py-1.5 rounded-lg bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 font-mono text-[11px]"
                    />
                  </>
                )}
                <button
                  type="submit"
                  disabled={submittingShipping}
                  className="w-full py-2 px-3 rounded-lg bg-slate-900 dark:bg-white text-white dark:text-slate-900 text-xs font-semibold transition-opacity"
                >
                  {submittingShipping ? 'Updating...' : 'Record Milestone'}
                </button>
              </form>
            </div>
          )}
        </div>

        {/* Staff Notes */}
        <div className="space-y-3">
          <h2 className="font-display text-sm font-bold text-slate-900 dark:text-white">
            Staff Notes (1-2000 chars)
          </h2>
          <form onSubmit={handleAddNote} className="flex gap-2">
            <input
              type="text"
              required
              maxLength={2000}
              value={noteInput}
              onChange={e => setNoteInput(e.target.value)}
              placeholder="Add internal operational note (visible to staff only)..."
              className="flex-1 px-4 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white focus:outline-none focus:border-emerald-500"
            />
            <button
              type="submit"
              disabled={submittingNote || !noteInput.trim()}
              className="px-4 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold disabled:opacity-50 inline-flex items-center gap-1.5"
            >
              <Send size={13} />
              <span>Add Note</span>
            </button>
          </form>

          {orderDetail.adminNotes && orderDetail.adminNotes.length > 0 && (
            <div className="space-y-2 pt-2">
              {orderDetail.adminNotes.map((note: any, i: number) => (
                <div key={i} className="p-3 rounded-xl bg-slate-50 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 text-xs space-y-1">
                  <div className="flex items-center justify-between text-[11px] text-slate-400 font-mono">
                    <span>Staff: {note.authorId || 'Operations'}</span>
                    <span>{new Date(note.createdAt).toLocaleString()}</span>
                  </div>
                  <p className="text-slate-800 dark:text-slate-200">{note.body}</p>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Chronological Event Timeline */}
        {timeline.length > 0 && (
          <div className="space-y-3">
            <h2 className="font-display text-sm font-bold text-slate-900 dark:text-white">
              Merged Event Timeline (Max 200 Events)
            </h2>
            <div className="divide-y divide-slate-100 dark:divide-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl overflow-hidden text-xs">
              {timeline.map((ev: any, idx: number) => (
                <div key={idx} className="p-3.5 flex items-center justify-between gap-4">
                  <div className="space-y-0.5">
                    <span className="font-mono font-bold text-slate-900 dark:text-white block">
                      {ev.type || ev.action || 'EVENT'}
                    </span>
                    <span className="text-slate-500 text-[11px]">
                      {ev.description || ev.message || JSON.stringify(ev.metadata || {})}
                    </span>
                  </div>
                  <span className="font-mono text-[11px] text-slate-400 shrink-0">
                    {new Date(ev.timestamp || ev.createdAt).toLocaleString()}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <ConfirmModal
        isOpen={confirmCancelOpen}
        onClose={() => setConfirmCancelOpen(false)}
        onConfirm={executeCancelOrder}
        title="Confirm Order Cancellation"
        message={`Are you sure you want to cancel order #${order.orderId}? This action will record an audited cancellation event and cannot be undone.`}
        isLoading={submittingCancel}
      />
    </div>
  );
};

export default AdminOrderDetail;
